var aplGridMap = { ref:['ref-80','ref-70w','ref-70','ref-75','ref-100'], cw:['cw-70w'] };

function aplBuildGrids() {
  for (var g in aplGridMap) {
    var el = document.getElementById('apl-grid-'+g); if(!el) continue;
    el.innerHTML = aplGridMap[g].map(function(k){
      var p=APL[k];
      return '<div class="apl-product-thumb" onclick="aplShowProd(\'' +k+ '\')"><div class="apl-thumb-img"><img src="'+p.img+'" alt="'+p.t+'" style="width:100%;height:100%;object-fit:cover;"></div><h5>'+p.t+'</h5></div>';
    }).join('');
  }
}
aplBuildGrids();

function aplShowCatalog(){document.getElementById('apl-catalog').style.display='block';document.getElementById('apl-detail').style.display='none';document.querySelectorAll('.apl-bc-detail').forEach(function(e){e.style.display='none';});window.scrollTo({top:document.getElementById('brand-andhra').offsetTop-120,behavior:'smooth'});}
function aplShowProd(k){
  var p=APL[k]; if(!p) return;
  document.getElementById('apl-catalog').style.display='none';
  document.getElementById('apl-detail').style.display='block';
  document.getElementById('apl-d-title').textContent=p.t;
  document.getElementById('apl-d-desc').textContent=p.d;
  document.getElementById('apl-d-img').src=p.img;
  document.getElementById('apl-d-img').alt=p.t;
  document.querySelectorAll('.apl-bc-detail').forEach(function(e){e.style.display='inline';});
  document.getElementById('apl-bc-product').textContent=p.t;
  document.getElementById('apl-af').innerHTML='<ul>'+p.f.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul>';
  document.getElementById('apl-as').innerHTML='<table><tr><th>Parameter</th><th>Unit</th><th>Spec</th></tr>'+p.s.map(function(r){return '<tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td>'+r[2]+'</td></tr>';}).join('')+'</table>';
  document.getElementById('apl-ab').innerHTML='<ul>'+p.b.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul>';
  document.getElementById('apl-ae').innerHTML='<ul>'+p.e.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul>';
  document.querySelectorAll('.apl-accordion-body').forEach(function(b){b.classList.remove('apl-open');});
  document.querySelectorAll('.apl-acc-icon').forEach(function(i){i.textContent='+';});
  window.scrollTo({top:document.getElementById('brand-andhra').offsetTop-120,behavior:'smooth'});
}
function aplToggleAcc(el){
  var bd=el.nextElementSibling,ic=el.querySelector('.apl-acc-icon');
  bd.classList.toggle('apl-open');
  ic.textContent=bd.classList.contains('apl-open')?'−':'+';
}

